<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Delivery Dashboard | ShopNest</title><link rel="stylesheet" href="style.css"></head><body><?php require __DIR__.'/../layout/header.php'; ?><main class="container cart-page"><div class="page-head"><span class="badge">Delivery Agent</span><h1>Delivery List</h1><p>View deliveries and update delivery status.</p></div><?php if($message): ?><p class="success-message">✓ <?= htmlspecialchars($message) ?></p><?php endif; ?><div class="table-wrap panel"><table><tr><th>Order</th><th>Customer</th><th>Address</th><th>Phone</th><th>Status</th><th>Update</th></tr><?php while($d=$deliveries->fetch_assoc()): ?><tr><td>#<?= $d['order_id'] ?></td><td><?= htmlspecialchars($d['customer_name']) ?></td><td><?= htmlspecialchars($d['customer_address']) ?></td><td><?= htmlspecialchars($d['customer_phone']) ?></td><td><?= htmlspecialchars($d['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="delivery_id" value="<?= $d['delivery_id'] ?>"><select name="status"><option>pending</option><option>shipped</option><option>delivered</option></select><input type="date" name="delivery_date" value="<?= htmlspecialchars($d['delivery_date']??'') ?>"><button class="btn btn-primary">Save</button></form></td></tr><?php endwhile; ?></table></div></main><?php require __DIR__.'/../layout/footer.php'; ?></body></html>
